/*
  ESP32: управление DC-мотором (через драйвер) + сервоприводом
  по сигналам от кнопки (NO) и концевика (NO).

  Логика работы:
  1. В покое (IDLE) сервопривод стоит в положении SERVO_MIN (100).
  2. Кнопка нажата -> запускается мотор на заданной скорости,
     сервопривод переходит в SERVO_MAX (125).
     Кнопка типа NC (нормально замкнута): в покое контакт замкнут
     на GND (пин = LOW), при нажатии контакт размыкается и пин
     подтягивается к VCC (пин = HIGH). Событие "нажатие" = переход
     LOW -> HIGH.
  3. Когда срабатывает концевик -> мотор останавливается.
  4. Через 20 секунд после остановки -> сервопривод возвращается
     в SERVO_MIN (100), система снова готова к работе (IDLE).

  Библиотека для серво: ESP32Servo
  (Arduino IDE -> Инструменты -> Управление библиотеками -> "ESP32Servo")
*/

#include <ESP32Servo.h>

// ---------------------- НАСТРОЙКИ ПИНОВ ----------------------
// Кнопка - нормально ЗАМКНУТА (NC): в покое пин=LOW (замкнут на GND),
// при нажатии контакт размыкается и пин уходит в HIGH (подтяжка к VCC).
// Концевик - нормально разомкнут (NO): в покое пин=HIGH, при срабатывании
// замыкается на GND и даёт LOW.
const int PIN_BUTTON      = 4;   // кнопка запуска (NC)
const int PIN_LIMIT       = 5;   // концевик (NO)

// Сервопривод (сигнальный провод)
const int PIN_SERVO       = 13;

// Драйвер мотора: направление IN1/IN2 + разрешение/скорость (PWM) на ENA
const int PIN_MOTOR_IN1   = 14;
const int PIN_MOTOR_IN2   = 27;
const int PIN_MOTOR_PWM   = 26;  // ENA, ШИМ (управление скоростью)

// ---------------------- ПАРАМЕТРЫ ----------------------------
const int SERVO_MIN_POS   = 100; // "меньшее" положение серво
const int SERVO_MAX_POS   = 125; // "большее" положение серво

const int MOTOR_SPEED     = 200; // скорость мотора, 0-255 (ШИМ)

const unsigned long DEBOUNCE_MS   = 50;    // антидребезг, мс
const unsigned long COOLDOWN_MS   = 20000; // пауза перед возвратом серво, мс

// ШИМ для мотора (классический ledc API, совместим со старыми и новыми ядрами)
const int MOTOR_PWM_CHANNEL = 0;
const int MOTOR_PWM_FREQ    = 5000;  // Гц
const int MOTOR_PWM_RES     = 8;     // бит (0-255)

// ---------------------- СОСТОЯНИЯ -----------------------------
enum SystemState {
  STATE_IDLE,      // ожидание нажатия кнопки
  STATE_RUNNING,   // мотор работает, ждём концевик
  STATE_COOLDOWN   // концевик сработал, ждём 20 сек перед возвратом серво
};

SystemState currentState = STATE_IDLE;
unsigned long cooldownStartTime = 0;

Servo myServo;

// ---------------------- АНТИДРЕБЕЗГ ----------------------------
// Кнопка NC: в покое LOW, при нажатии HIGH -> стартовое стабильное состояние LOW.
bool lastButtonReading   = LOW;
bool stableButtonState   = LOW;
unsigned long lastButtonChangeTime = 0;

bool lastLimitReading     = HIGH;
bool stableLimitState     = HIGH;
unsigned long lastLimitChangeTime = 0;

// Возвращает true один раз в момент "нажатия" кнопки NC (переход LOW->HIGH)
bool buttonPressedEdge() {
  bool reading = digitalRead(PIN_BUTTON);

  if (reading != lastButtonReading) {
    lastButtonChangeTime = millis();
  }

  bool edge = false;
  if ((millis() - lastButtonChangeTime) > DEBOUNCE_MS) {
    if (reading != stableButtonState) {
      stableButtonState = reading;
      if (stableButtonState == HIGH) {
        edge = true; // зафиксировано нажатие (контакт NC разомкнулся)
      }
    }
  }

  lastButtonReading = reading;
  return edge;
}

// Возвращает true один раз в момент срабатывания концевика (переход HIGH->LOW)
bool limitTriggeredEdge() {
  bool reading = digitalRead(PIN_LIMIT);

  if (reading != lastLimitReading) {
    lastLimitChangeTime = millis();
  }

  bool edge = false;
  if ((millis() - lastLimitChangeTime) > DEBOUNCE_MS) {
    if (reading != stableLimitState) {
      stableLimitState = reading;
      if (stableLimitState == LOW) {
        edge = true; // зафиксировано срабатывание концевика
      }
    }
  }

  lastLimitReading = reading;
  return edge;
}

// ---------------------- УПРАВЛЕНИЕ МОТОРОМ ----------------------
void motorStart() {
  // направление вращения - вперёд (при необходимости поменяйте местами IN1/IN2)
  digitalWrite(PIN_MOTOR_IN1, HIGH);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  ledcWrite(MOTOR_PWM_CHANNEL, MOTOR_SPEED);
  Serial.println("Мотор: СТАРТ");
}

void motorStop() {
  digitalWrite(PIN_MOTOR_IN1, LOW);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  ledcWrite(MOTOR_PWM_CHANNEL, 0);
  Serial.println("Мотор: СТОП");
}

// ---------------------- SETUP ----------------------
void setup() {
  Serial.begin(115200);

  pinMode(PIN_BUTTON, INPUT_PULLUP); // NC: в покое LOW, при нажатии HIGH
  pinMode(PIN_LIMIT, INPUT_PULLUP);  // NO: в покое HIGH, при срабатывании LOW

  pinMode(PIN_MOTOR_IN1, OUTPUT);
  pinMode(PIN_MOTOR_IN2, OUTPUT);
  digitalWrite(PIN_MOTOR_IN1, LOW);
  digitalWrite(PIN_MOTOR_IN2, LOW);

  // Настройка ШИМ-канала для мотора
  ledcSetup(MOTOR_PWM_CHANNEL, MOTOR_PWM_FREQ, MOTOR_PWM_RES);
  ledcAttachPin(PIN_MOTOR_PWM, MOTOR_PWM_CHANNEL);
  ledcWrite(MOTOR_PWM_CHANNEL, 0);

  // Инициализация серво
  ESP32PWM::allocateTimer(0);
  myServo.setPeriodHertz(50);
  myServo.attach(PIN_SERVO, 500, 2400); // диапазон импульсов можно подстроить под вашу модель серво
  myServo.write(SERVO_MIN_POS);         // стартовое положение - "меньшее"

  currentState = STATE_IDLE;
  Serial.println("Система готова (IDLE)");
}

// ---------------------- LOOP ----------------------
void loop() {
  bool buttonEdge = buttonPressedEdge();
  bool limitEdge  = limitTriggeredEdge();

  switch (currentState) {

    case STATE_IDLE:
      if (buttonEdge) {
        motorStart();
        myServo.write(SERVO_MAX_POS);
        currentState = STATE_RUNNING;
        Serial.println("Переход в состояние: RUNNING");
      }
      break;

    case STATE_RUNNING:
      if (limitEdge) {
        motorStop();
        cooldownStartTime = millis();
        currentState = STATE_COOLDOWN;
        Serial.println("Концевик сработал. Переход в состояние: COOLDOWN");
      }
      break;

    case STATE_COOLDOWN:
      if (millis() - cooldownStartTime >= COOLDOWN_MS) {
        myServo.write(SERVO_MIN_POS);
        currentState = STATE_IDLE;
        Serial.println("20 сек прошло. Серво возвращено. Переход в состояние: IDLE");
      }
      break;
  }
}
